import{_ as e,o,c as t,a2 as d}from"./chunks/framework.CqGPl1zp.js";const i="/newx-doc/assets/%E6%A8%A1%E6%8B%9F%E6%94%AF%E4%BB%98%E5%BC%80%E5%90%AF.DFJcFtan.png",r="/newx-doc/assets/%E6%A8%A1%E6%8B%9F%E6%94%AF%E4%BB%98.DfPrUbx_.png",m=JSON.parse('{"title":"模拟支付、退款","description":"","frontmatter":{},"headers":[],"relativePath":"pay/mock.md","filePath":"pay/mock.md","lastUpdated":null}'),l={name:"pay/mock.md"};function p(n,a,c,s,_,h){return o(),t("div",null,[...a[0]||(a[0]=[d('<h1 id="模拟支付、退款" tabindex="-1">模拟支付、退款 <a class="header-anchor" href="#模拟支付、退款" aria-label="Permalink to &quot;模拟支付、退款&quot;">​</a></h1><p>前置阅读：</p><p>需要先阅读如下文档，对支付、退款功能有一定了解：</p><ul><li><a href="./build">《支付功能开启》</a></li><li><a href="./alipay-pay-demo">《支付宝支付接入》</a></li><li><a href="./refund-demo">《支付宝、微信退款接入》</a></li></ul><p>考虑到支付、退款功能的接入，需要依赖支付宝、微信等支付渠道，会比较麻烦。所以，我们提供了模拟支付、退款的功能，方便开发者进行接入。</p><p>具体的实现，可见 MockPayClient 客户端：</p><ul><li>在 <code>#doUnifiedOrder(...)</code> 方法中，直接返回支付【成功】</li><li>在 <code>#doUnifiedRefund(...)</code> 方法中，直接返回退款【成功】</li></ul><p>下面，我们以“商城”为例子，讲解模拟支付的开启、使用。</p><h2 id="_1-模拟支付的开启" tabindex="-1">1. 模拟支付的开启 <a class="header-anchor" href="#_1-模拟支付的开启" aria-label="Permalink to &quot;1. 模拟支付的开启&quot;">​</a></h2><p>在管理后台的 [支付管理 -&gt; 应用信息] 菜单，将商城对应的支付应用 <code>mall</code> 进行开启（开启状态为打开）。如下图所示：</p><p><img src="'+i+'" alt="模拟支付开启"></p><h2 id="_2-模拟支付的使用" tabindex="-1">2. 模拟支付的使用 <a class="header-anchor" href="#_2-模拟支付的使用" aria-label="Permalink to &quot;2. 模拟支付的使用&quot;">​</a></h2><p>在商城 uni-app 收银台，选择“模拟支付”时，内部会调用 MockPayClient 的 <code>#doUnifiedOrder(...)</code> 方法，发起支付，直接成功。</p><p>它的整体流程和 <a href="./alipay-pay-demo">《支付宝支付接入》</a> 是类似的。</p><p><img src="'+r+'" alt="模拟支付"></p><h2 id="_3-模拟退款的使用" tabindex="-1">3. 模拟退款的使用 <a class="header-anchor" href="#_3-模拟退款的使用" aria-label="Permalink to &quot;3. 模拟退款的使用&quot;">​</a></h2><p>模拟支付后，如果发起退款，内部会调用 MockPayClient 的 <code>#doUnifiedRefund(...)</code> 方法，发起退款，直接成功。</p><p>它的整体流程和 <a href="./refund-demo">《支付宝、微信退款接入》</a> 是类似的。</p>',18)])])}const u=e(l,[["render",p]]);export{m as __pageData,u as default};
